arguments.command:
cd /workspace/project && cat > include/offline_api.h <<'EOF'
#ifndef OFFLINE_API_H
#define OFFLINE_API_H
#include <stdint.h>
#include <stddef.h>

/* Offline replay ABI. Nothing here performs live I/O: the collector is driven
 * entirely by expanded event descriptors and returns certificates in memory. */

enum {
    EPIC_EV_DATA = 0,   /* rank,p[,count,step,seed,values,xor] */
    EPIC_EV_ACK = 1,    /* rank,upto */
    EPIC_EV_WIRE = 2,   /* rank,wire bytes */
    EPIC_EV_BUDGET = 3, /* n */
    EPIC_EV_FLUSH = 4,
    EPIC_EV_RETRY = 5,  /* rank */
    EPIC_EV_SNAP = 6,
    EPIC_EV_TRAIN = 7,  /* p,count,width,ranks[,reverse,seed] */
};

#define EPIC_MAX_FRAME_BYTES 4160

typedef struct {
    int32_t op, rank, p, count, step, width, upto, n;
    uint32_t seed;
    int32_t reverse, nxor, wire_len;
    int32_t ranks[4];
    const uint32_t *values;
    const int32_t *xors;
    const uint8_t *wire;
} epic_event_t;

typedef struct {
    uint64_t state[32];
    uint64_t buffer;
    uint8_t sha[32];
    uint64_t packets, bytes;
} epic_snap_t;

typedef struct {
    uint32_t len;
    uint8_t rank;
    uint8_t frame[EPIC_MAX_FRAME_BYTES];
} epic_trace_t;

typedef struct {
    uint64_t state[32];
    uint64_t buffer;
    uint8_t sha[32];
    uint64_t packets, bytes;
    uint32_t snap_count, trace_count;
    const epic_snap_t *snaps;
    const epic_trace_t *trace;
} epic_result_t;

void *epic_open(int primitive, int mode, int root, uint32_t segments, uint32_t words,
                uint32_t capacity, uint32_t start, uint32_t trace);
void epic_close(void *context);
void epic_run(void *context, const epic_event_t *events, int32_t count);
void epic_ingress(void *context, int rank, const uint8_t *frame, size_t length);
void epic_flush(void *context);
void epic_retry(void *context, int rank);
const epic_result_t *epic_result(void *context);
uint64_t epic_sizeof_result(void);
#endif
EOF
echo ok
